script:
if (-not $SHARE_NAME -or -not $SHARE_PATH) { throw 'SHARE_NAME and SHARE_PATH are required' }
Start-Service LanmanServer -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force -Path $SHARE_PATH | Out-Null
$share = Get-SmbShare -Name $SHARE_NAME -ErrorAction SilentlyContinue
if ($share) {
    Grant-SmbShareAccess -Name $SHARE_NAME -AccountName 'Everyone' -AccessRight Full -Force | Out-Null
} else {
    New-SmbShare -Name $SHARE_NAME -Path $SHARE_PATH -FullAccess 'Everyone' -Description $DESCRIPTION | Out-Null
}
